\n    \"docs/CHANGELOG.md\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\",\n    \"docs/NOTICE.md\",\n    \"packages/client/src/features/sodium/LICENSE\",\n    \"docs/THIRD_PARTY_NOTICES.md\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"cordis\",\n    \"web-ui\",\n    \"theme\",\n    \"claude\",\n    \"claude-code\",\n    \"desktop-theme\",\n    \"anthropic\",\n    \"editorial\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"Nwflower\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Nwflower/dsh-claude-style.git\"\n  },\n  \"homepage\": \"https://github.com/Nwflower/dsh-claude-style#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Nwflower/dsh-claude-style/issues\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.5-rc.1\",\n    \"@deepseek-ai/schemastery\": \">=3.18.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-alpha.1\",\n    \"@deepseek-ai/schemastery\": \"3.18.4\",\n    \"@types/node\": \"^26.6.4\",\n    \"@types/react\": \"18.3.31\",\n    \"@types/react-dom\": \"18.3.7\",\n    \"@vitest/browser-playwright\": \"5.0.3\",\n    \"ajv\": \"8.20.0\",\n    \"ajv-formats\": \"3.0.1\",\n    \"culori\": \"4.0.2\",\n    \"esbuild\": \"0.28.2\",\n    \"fast-check\": \"4.10.2\",\n    \"jscpd\": \"5.3.3\",\n    \"playwright\": \"1.63.0\",\n    \"pngjs\": \"^7.0.0\",\n    \"postcss\": \"8.5.29\",\n    \"postcss-selector-parser\": \"7.1.6\",\n    \"typescript\": \"7.0.2\",\n    \"vitest\": \"5.0.3\"\n  }\n}\n"
