      "path": "packages/client/src/features/sodium/sodium-engine.ts",
      "content": "import { PLUGIN_SHEET_OWNER_ATTRIBUTE, PLUGIN_SHEET_PATH_ATTRIBUTE, PLUGIN_SHEET_SELECTOR } from '@dsh-claude-style/contracts/dom'\nimport { profileBundles } from '@dsh-claude-style/engine/host'\nimport { applyRewrite, planRewrite, restoreRewrite } from '@dsh-claude-style/engine/sheet-rewrite'\nimport type { HostContext } from '@dsh-claude-style/engine/host'\nimport type { RewrittenRule } from '@dsh-claude-style/engine/sheet-rewrite'\nimport { SODIUM_MEMBERS } from './members'\nimport type { SodiumAdapter, SodiumMember } from './members'\nimport { publishLost, publishRules } from './sodium-state'\nimport { versionAtLeast } from './version'\n\n/** One sheet the rewrite holds, under the adapter that rewrote it. */\ninterface HeldSheet {\n  readonly sheet: CSSStyleSheet\n  readonly member: SodiumMember\n  readonly adapter: SodiumAdapter\n  readonly rules: readonly RewrittenRule[]\n}\n\n/**\n * The release each member is on, or null where it cannot be read. The host's\n * is in its boot graph; a plugin's comes from the profile's bundle list, asked\n * only when the table carries a plugin member.\n */\nfunction readReleases(ctx: HostContext): Promise<Map<SodiumMember, string | null>> {\n  const host = window.__DSH_BOOT__?.release?.version\n  const bundles = SODIUM_MEMBERS.some((member) => member.release === 'bundle') ? profileBundles(ctx) : null\n  // A bundle list that fails leaves the plugin members unread and the host's\n  // rules still rewritten (D12); reportError surfaces the failure.\n  const listed = (bundles ?? Promise.resolve([])).catch((error: unknown) => {\n    reportError(error)\n    return []\n  })\n  return listed.then((list) => new Map(SODIUM_MEMBERS.map((member) => {\n    if (member.release === 'host') return [member, typeof host === 'string' ? host : null]\n    return [member, list.find((bundle) => bundle.name === member.id)?.version ?? null]\n  })))\n}\n\n/** The sheets on the page that one adapter names, as the loader tagged them. */\nfunction sheetsOf(adapter: SodiumAdapter) {\n  const sheets: CSSStyleSheet[] = []\n  for (const node of document.head.querySelectorAll<HTMLStyleElement>(PLUGIN_SHEET_SELECTOR)) {\n    if (node.getAttribute(PLUGIN_SHEET_OWNER_ATTRIBUTE) !== adapter.owner || node.getAttribute(PLUGIN_SHEET_PATH_ATTRIBUTE) !== adapter.sheet) continue\n    if (node.sheet !== null) sheets.push(node.sheet)\n  }\n  return sheets\n}\n\n/**\n * The rewrite itself (D78): on, it rewrites every listed rule on the page and\n * keeps the attributes the rewritten rules read; off, the sheets and the page\n * are the owners' again. `refresh` follows the sheets coming and going while it\n * is on, and `survey` counts what it would rewrite, for the first probe.\n */\nexport function createSodiumEngine(ctx: HostContext) {\n  const releases = readReleases(ctx)\n  let on = false\n  let held: HeldSheet[] = []\n  /** The sheets the table held on the last report, and whether their loss has been reported since. */\n  let lastSheets: readonly string[] = []\n  let reportedLoss = false\n  /** Each adapter's attribute keeper, with the captured classes it keeps them for. */\n  const keepers = new Map<SodiumAdapter, { key: string, stop: () => void }>()\n\n  /** The members whose release the table covers. */\n  const coveredMembers = () => releases.then((known) => SODIUM_MEMBERS.filter((member) => {\n    const release = known.get(member)\n    return release !== null && release !== undefined && versionAtLeast(release, member.since)\n  }))\n\n  /**\n   * Report what the rewrite holds. A table that held rules on a sheet and holds\n   * none of them now was overtaken by its owner's change, which the page shows\n   * nowhere else: the loss is named once.\n   */\n  function publish() {\n    const rules = held.flatMap(({ member, adapter, rules }) => rules.map((entry) => ({\n      member: member.id,\n      since: member.since,\n      sheet: adapter.sheet,\n      declarations: entry.rule.style.cssText,\n    })))\n    publishRules(rules)\n    const lost = on && rules.length === 0 && lastSheets.length > 0\n    if (lost && !reportedLoss) reportError(new Error(`sodium: ${lastSheets.join(', ')} no longer carry the rules the table rewrites`))\n    reportedLoss = lost\n    publishLost(lost ? lastSheets : [])\n    lastSheets = [...new Set(held.map(({ adapter }) => adapter.sheet))]\n  }\n\n  /**\n   * A sheet that refuses a rewritten selector: `applyRewrite` has written that\n   * sheet's own rules back, so it stays its owner's while the sheets taken\n   * before it stay restorable and reported (D12).\n   */\n  function reportWrite(error: unknown) {\n    reportError(error)\n    publish()\n  }\n\n  /** Start, restart or stop each adapter's keeper for the classes its rules captured, by role. */\n  function keep(planned: readonly HeldSheet[]) {\n    const captured = new Map<SodiumAdapter, Map<string, Set<string>>>()\n    for (const { adapter, rules } of planned) {\n      const roles = captured.get(adapter) ?? new Map<string, Set<string>>()\n      for (const entry of rules) {\n        for (const [role, name] of Object.entries(entry.captured)) roles.set(role, (roles.get(role) ?? new Set<string>()).add(name))\n      }\n      captured.set(adapter, roles)\n    }\n    for (const [adapter, keeper] of keepers) {\n      if (captured.has(adapter)) continue\n      keeper.stop()\n      keepers.delete(adapter)\n    }\n    for (const [adapter, roles] of captured) {\n      const named = new Map([...roles].map(([role, names]) => [role, [...names].sort()]))\n      const key = JSON.stringify([...named].sort(([a], [b]) => a < b ? -1 : 1))\n      if (keepers.get(adapter)?.key === key) continue\n      keepers.get(adapter)?.stop()\n      keepers.set(adapter, { key, stop: adapter.maintain(named) })\n    }\n  }\n\n  /** The rules of a sheet some adapter holds or is about to: the next adapter leaves them alone. */\n  function takenIn(sheet: CSSStyleSheet, entries: readonly HeldSheet[]) {\n    return new Set(entries.filter((entry) => entry.sheet === sheet).flatMap((entry) => entry.rules.map((rule) => rule.rule)))\n  }\n\n  /**\n   * Bring the held sheets up to the page: a sheet whose node left or was given\n   * a new sheet is gone with its rewrite, and a listed sheet not held yet is\n   * rewritten. The keepers start before the selectors change, both in this one\n   * task, so no frame reads a rewritten rule without its attribute.\n   */\n  function sync(members: readonly SodiumMember[]) {\n    if (!on) return\n    held = held.filter(({ sheet }) => sheet.ownerNode instanceof HTMLStyleElement && sheet.ownerNode.isConnected && sheet.ownerNode.sheet === sheet)\n    const fresh: HeldSheet[] = []\n    for (const member of members) {\n      for (const adapter of member.adapters) {\n        for (const sheet of sheetsOf(adapter)) {\n          if (held.some((entry) => entry.sheet === sheet && entry.adapter === adapter)) continue\n          const rules = planRewrite(sheet, adapter, takenIn(sheet, [...held, ...fresh]))\n          if (rules.length > 0) fresh.push({ sheet, member, adapter, rules })\n        }\n      }\n    }\n    keep([...held, ...fresh])\n    // Each sheet is held as it is written: a sheet the browser refuses takes its\n    // own rules back, and the sheets taken before it stay restorable.\n    for (const entry of fresh) held.push({ ...entry, rules: applyRewrite(entry.rules) })\n    publish()\n  }\n\n  return {\n    start() {\n      if (on) return\n      on = true\n      coveredMembers().then(sync).catch(reportWrite)\n    },\n    /** Follow the sheets in `<head>` while on. */\n    refresh() {\n      if (on) coveredMembers().then(sync).catch(reportWrite)\n    },\n    stop() {\n      if (!on) return\n      on = false\n      // A rule another writer changed since keeps its rewritten selector, and the\n      // marks come off below: from here on it matches nothing, so it is named.\n      const stranded = held.flatMap(({ adapter, rules }) => restoreRewrite(rules).map((entry) => `${adapter.sheet} · ${entry.rewritten}`))\n      held = []\n      keep([])\n      publish()\n      if (stranded.length > 0) reportError(new Error(`sodium: ${stranded.join('; ')} no longer read as the rewrite left them and stay written`))\n    },\n    /** How many rules the rewrite would take on the page as it stands. */\n    survey() {\n      return coveredMembers().then((members) => members.reduce((count, member) => count + member.adapters.reduce(\n        (sum, adapter) => sum + sheetsOf(adapter).reduce((rules, sheet) => rules + planRewrite(sheet, adapter).length, 0),\n        0,\n      ), 0))\n    },\n  }\n}\n"
    },
    {
      "path": "packages/client/src/features/sodium/sodium.ts",
      "content": "import { SODIUM_ON, SODIUM_UNDECIDED } from '../../constants'\nimport { prefsFromForm, readPrefs, savePrefs, subscribePrefs } from '../../core/prefs'\nimport { subscribeMutations } from '@dsh-claude-style/engine/bus'\nimport type { HostContext } from '@dsh-claude-style/engine/host'\nimport { createSodiumEngine } from './sodium-engine'\n\n/**\n * The sodium rewrite (D78): the host's and the plugins' costly style rules,\n * rewritten in place to read attributes this skin keeps, while the reader has\n * the switch on.\n *\n * The feature is installed whatever the switch says, because the switch starts\n * undecided: while it is, every look at the page is a probe, and the first one\n * that finds a listed rule turns the switch on for the reader. From the first\n * time the reader flips it, the switch holds a decided value the probe leaves\n * alone. `<head>` is watched for the sheets coming and going: a plugin module\n * that loads late injects its sheet after this install, and a sheet injected\n * again is a new object carrying none of the rewrite.\n */\nexport function install(ctx: HostContext) {\n  const engine = createSodiumEngine(ctx)\n  let disposed = false\n  /** A probe's write is on its way: the next look waits for the form to answer. */\n  let probing = false\n\n  function probe() {\n    if (probing || !prefsFromForm() || readPrefs().sodium !== SODIUM_UNDECIDED) return\n    probing = true\n    engine.survey().then((count) => {\n      if (disposed || count === 0 || readPrefs().sodium !== SODIUM_UNDECIDED) return null\n      return savePrefs({ sodium: SODIUM_ON })\n    }).finally(() => { probing = false })\n  }\n\n  function follow() {\n    if (readPrefs().sodium === SODIUM_ON) engine.start()\n    else engine.stop()\n    probe()\n  }\n\n  const stopPrefs = subscribePrefs(follow)\n  const stopHead = subscribeMutations(document.head, { childList: true, subtree: true }, () => {\n    engine.refresh()\n    probe()\n  })\n  follow()\n\n  return () => {\n    disposed = true\n    stopPrefs()\n    stopHead()\n    engine.stop()\n  }\n}\n"
    },
    {
      "path": "packages/client/src/features/workspace/workspace-view.ts",
      "content": "import * as React from 'react'\nimport * as primitives from '@deepseek-ai/dsh-client-ui-primitives'\nimport { SESSION_DELETE_ROUTE } from '../../constants'\nimport { hostSessions, hostWorkspaceView, registerSlotEntries } from '@dsh-claude-style/engine/host'\nimport { observeMatches, subscribeMutations } from '@dsh-claude-style/engine/bus'\nimport type { MatchList } from '@dsh-claude-style/engine/bus'\nimport { buildElement, closestFrom, createStamp } from '@dsh-claude-style/engine/dom'\nimport { markPartsWithin } from '@dsh-claude-style/engine/parts'\nimport { createHostToast } from '../../shared/host-toast'\nimport { VIEW_SWITCH_CLASS } from '../../shared/segment-control'\nimport type { HostAnswer } from '@dsh-claude-style/engine/resource'\nimport { createSlidingPill } from '../../shared/sliding-pill'\nimport type { HostContext } from '@dsh-claude-style/engine/host'\nimport type { HostArchivedFilter, HostSessionsService, HostSessionGroupBy, HostWorkspaceViewSnapshot, HostWorkspaceViewStore } from '@dsh-claude-style/contracts/services'\nimport type { FeatureUi } from '../../core/feature'\nimport type manifest from './workspace-view.manifest'\nimport { copy } from './copy'\nimport type { CopyKey } from './copy'\n\n/** The row-action list the host's session rows render; the skin's delete button stands beside unarchive. */\nconst SESSION_ROW_ACTION_SLOT = 'sidebar.workspaces.session.row.action'\n/** The reader's 进行中 grouping, outliving a reload spent in 已归档. */\nconst GROUP_BY_STORAGE = 'dsh-claude-style.workspaceGroupBy'\n\n/** The grouping the reader last had in 进行中: the store's default until this browser records one. */\nfunction storedGroupBy(): HostSessionGroupBy {\n  const stored = localStorage.getItem(GROUP_BY_STORAGE)\n  return stored === 'workspace-tree' || stored === 'flat' ? stored : 'workspace'\n}\n\nfunction storeGroupBy(group: HostSessionGroupBy) {\n  localStorage.setItem(GROUP_BY_STORAGE, group)\n}\n\n/** The store's filter, with a snapshot older than the filter read as the host reads it. */\nfunction filterOf(snapshot: HostWorkspaceViewSnapshot): HostArchivedFilter {\n  return snapshot.archivedFilter === 'show' || snapshot.archivedFilter === 'only' ? snapshot.archivedFilter : 'default'\n}\n\nfunction groupOf(snapshot: HostWorkspaceViewSnapshot): HostSessionGroupBy {\n  return snapshot.groupBy === 'workspace-tree' || snapshot.groupBy === 'flat' ? snapshot.groupBy : 'workspace'\n}\n\n/**\n * The sidebar's workspace section, re-cut as a two-state view of the host's own\n * browser.\n *\n * The host's view store is the state: 进行中 is its 隐藏已归档 filter and\n * 已归档 its 仅显示已归档 filter over the one flat list, so both segments show\n * the host's own tree — its rows, its unarchive button, its archived-row notice\n * — rather than a list of the skin's. The store is reached through the\n * registration the host keeps under `sidebar.workspaces` (package\n * `@dsh-claude-style/engine/host.ts` `hostWorkspaceView`), the same instance its\n * own view menu writes; the grouping the reader had before 已归档 is put back on\n * the way out, and kept in this browser for a reload spent inside 已归档.\n *\n * The archived list carries no delete action of the host's, so the skin\n * registers one in the host's row-action seat (`sidebar.workspaces.session.row.action`),\n * rendered only while the archived filter stands. Deleting goes through the\n * host half's route (D75) as it did on the skin's own rows.\n *\n * The filter is the store's: a change made through the host's view menu, or the\n * archive notice's 「筛选已归档会话」, lands in the segment too — the notice asks\n * to see the archived conversations, which is the archived segment. The two\n * archived-showing filters both mean that segment, so `show` is driven to\n * `only`; `default` is 进行中.\n */\nexport function install(ctx: HostContext, ui: FeatureUi<typeof manifest>) {\n  /** The host's Toast and icons, reached through the plugin loader's `require` — the same packages its UI uses. */\n  const toast = createHostToast()\n  /** The section's view (active / archived), its heading, marked for workspace.css. */\n  const viewStamp = createStamp('data-dsh-claude-ws-view')\n  const labelStamp = createStamp('data-dsh-claude-ws-label')\n  const SEGMENTS: { id: string, key: CopyKey }[] = [\n    { id: 'active', key: 'archiveActive' },\n    { id: 'archived', key: 'archiveArchived' }\n  ]\n  let view: 'active' | 'archived' = 'active'\n  let control: HTMLElement | null = null\n  /** The control's sliding highlight (packages/client/src/shared/sliding-pill.ts). */\n  const segmentPill = createSlidingPill('[aria-checked=\"true\"]')\n  /** The host's view store; null until its registration is on the page. */\n  let store: HostWorkspaceViewStore | null = null\n  /** The session list, pulled after a delete so the removed summary leaves. */\n  let sessions: HostSessionsService | null = null\n  /**\n   * The filter the store answered last: a write of the skin's own is not read\n   * back as a change of the reader's, and the filter before an archived visit\n   * is what tells a return from a pick.\n   */\n  let seenFilter: HostArchivedFilter | null = null\n  /** The grouping 进行中 had before 已归档; see storedGroupBy for the reload case. */\n  let activeGroupBy: HostSessionGroupBy = storedGroupBy()\n  /** The archived row action's listeners (React's external-store subscription). */\n  const viewListeners: (() => void)[] = []\n  /**\n   * The section label, kept while it still stands; the section is a seat the\n   * host mounts once and replaces whole, and this runs on every pass.\n   */\n  let sectionLabel: HTMLElement | null = null\n  /** The section labels on the page, taken from the bus and released with the section. */\n  let labelWatch: MatchList<HTMLElement> | null = null\n  /** The list's additions, marked before the frame paints; see watchAdditions. */\n  let stopAdditions: (() => void) | null = null\n  let additionsRoot: Element | null = null\n  /** The slot service's injected scope, released with this install. */\n  let slotsFiber: { dispose?: () => void } | null = null\n  let disposed = false\n\n  /** The section root a label sits in: the label's header, and that header's parent. */\n  function sectionRoot(label: Element) {\n    const header = label.parentElement\n    return header === null ? null : header.parentElement\n  }\n  /** The section root a label stands in, or null when that root keeps no list area. */\n  function sectionOf(label: Element) {\n    const root = sectionRoot(label)\n    if (root === null) return null\n    return root.querySelector(LIST_AREA_SELECTOR) === null ? null : root\n  }\n  function findSection() {\n    const kept = sectionLabel\n    if (kept !== null && kept.isConnected && sectionOf(kept) !== null) return kept\n    // The labels of every section the sidebar holds, kept current by the bus\n    // (D40): which one dresses a control is decided here per pass, but the\n    // document is walked once rather than on every pass.\n    labelWatch ??= observeMatches<HTMLElement>('[data-dsh-claude-part~=\"section-label\"]')\n    const labels = labelWatch.all()\n    for (let i = 0; i < labels.length; i++) {\n      if (sectionOf(labels[i]) === null) continue\n      sectionLabel = labels[i]\n      return labels[i]\n    }\n    sectionLabel = null\n    return null\n  }\n\n  /** The section's list area, the sibling its header shares a parent with. */\n  const LIST_AREA_SELECTOR = '[data-dsh-claude-part~=\"list-area\"]'\n\n  /** The archived row action's subscription: the host renders it, the skin only re-renders it. */\n  function subscribeView(listener: () => void) {\n    viewListeners.push(listener)\n    return () => {\n      const at = viewListeners.indexOf(listener)\n      if (at !== -1) viewListeners.splice(at, 1)\n    }\n  }\n\n  function archivedView() {\n    return view === 'archived'\n  }\n\n  function notifyView() {\n    const listeners = viewListeners.slice()\n    for (let i = 0; i < listeners.length; i++) listeners[i]()\n  }\n\n  function setView(next: 'active' | 'archived') {\n    if (next === view) return\n    view = next\n    notifyView()\n  }\n\n  /** The reader's grouping, kept for the way back and across a reload inside 已归档. */\n  function rememberGroup(group: HostSessionGroupBy) {\n    activeGroupBy = group\n    storeGroupBy(group)\n  }\n\n  /**\n   * Follow the host's store. Its view menu and the archive notice's\n   * 「筛选已归档会话」 write the same state, so a change made there moves the\n   * segment with it; `show` (archived rows among the others) is the one state\n   * the two halves cannot share, and it is driven to `only` for the archived\n   * segment to own the list. A grouping change while 进行中 is the reader's and\n   * becomes the one a later 已归档 visit puts back.\n   */\n  function reconcile() {\n    const followed = store\n    if (followed === null || disposed) return\n    const snapshot = followed.getSnapshot()\n    const filter = filterOf(snapshot)\n    const group = groupOf(snapshot)\n    const previous = seenFilter\n    seenFilter = filter\n    if (filter === 'default') {\n      setView('active')\n      if (previous === 'only' || previous === 'show') {\n        if (group !== activeGroupBy) followed.actions.setGroupBy(activeGroupBy)\n      } else if (group !== activeGroupBy) {\n        rememberGroup(group)\n      }\n      return\n    }\n    setView('archived')\n    // The flat list 已归档 runs in is the skin's arrangement, not the reader's\n    // grouping: only a filter that was not already the archived one tells the\n    // two apart.\n    if (previous === 'default') rememberGroup(group)\n    else if (previous === null && group !== 'flat') rememberGroup(group)\n    if (filter !== 'only') followed.actions.setArchivedFilter('only')\n    if (group !== 'flat') followed.actions.setGroupBy('flat')\n  }\n\n  /**\n   * The segment's own switch: write the host's filter and grouping, then let\n   * the next pass follow the store's answer. The store keeps both, so the\n   * choice survives a reload without the skin persisting anything but the\n   * 进行中 grouping.\n   */\n  function drive(next: 'active' | 'archived') {\n    const followed = store\n    if (followed === null) return\n    if (next === 'archived') {\n      const snapshot = followed.getSnapshot()\n      if (filterOf(snapshot) === 'default') rememberGroup(groupOf(snapshot))\n      followed.actions.setArchivedFilter('only')\n      followed.actions.setGroupBy('flat')\n      seenFilter = 'only'\n    } else {\n      followed.actions.setArchivedFilter('default')\n      followed.actions.setGroupBy(activeGroupBy)\n      seenFilter = 'default'\n    }\n    setView(next)\n    sync()\n  }\n\n  /**\n   * The host's Toast, warning glyph included, rendered by the skin itself: the\n   * host's notice channel is private to ui-workspace. The Toast portals to the\n   * body, and a new key restarts it the way the host re-shows it.\n   */\n  function notifyToast(text: string) {\n    toast.show({ text, icon: React.createElement(primitives.IconWarningOutlineRegular) })\n  }\n\n  /**\n   * Delete one stored session through the host half's own route.\n   *\n   * The harness gives the browser half no deletion API of its own (the\n   * workspace controller archives and unarchives; the agent protocol's\n   * session delete is the host delegating to an ACP agent that owns the\n   * storage), so the skin's host half removes the session's stored\n   * directory and drops the id from the registry's archive set before it\n   * answers. A stored-directory miss answers success too — an archive\n   * entry whose directory is already gone is the ghost this buries — and\n   * a 404 that still carries the host's own \"session not found\" JSON is\n   * the same miss from an older host half without that branch: the storage\n   * is gone all the same, so the row leaves too. Every other refusal keeps\n   * the row and raises the host's Toast: the \"session is open\" answer (the\n   * app still holds the session's agent attached, and only a restart\n   * releases it) carries its own copy, everything else names the refusal\n   * the route sent.\n   */\n  function removeArchived(id: string) {\n    fetch(SESSION_DELETE_ROUTE, {\n      method: 'POST',\n      credentials: 'same-origin',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ sessionId: id }),\n    }).then(response => response.json().then((result: HostAnswer) => ({ status: response.status, result }))).then(({ status, result }) => {\n      if (result?.ok === true || (status === 404 && result?.error === 'session not found')) {\n        refreshSessions()\n        return\n      }\n      const refusal: Error & { status?: number } = new Error(String(result?.error || `HTTP ${status}`))\n      refusal.status = status\n      throw refusal\n    }).catch((reason: { status?: number, message?: string }) => {\n      console.warn('dsh-claude-style: session delete rejected:', reason)\n      notifyToast(reason?.status === 409\n        ? copy('archiveDeleteOpen')\n        : copy('archiveDeleteFailed', { detail: reason?.message ?? String(reason) }))\n    })\n  }\n\n  /**\n   * Re-pull the host's session baseline right after a delete.\n   *\n   * The full list is what the projection prunes by: the host's fresh list\n   * answer no longer carries the removed id, so its stale summary — the\n   * one that kept a deleted session looking alive — leaves `sessions.list`\n   * at this pull instead of at the next reconnect, and the host's own tree\n   * drops the row with it. The pull is the sessions service's single-flight\n   * refresh, so a pull already under way is reused.\n   */\n  function refreshSessions() {\n    const followed = sessions\n    if (followed === null || typeof followed.refresh !== 'function') return\n    // Best effort against the host's sessions service: a rejection leaves the list as it stands (D12).\n    followed.refresh().catch((reason: unknown) => {\n      console.warn('dsh-claude-style: session baseline refresh rejected:', reason)\n    })\n  }\n\n  /**\n   * The archived row's delete action. The host renders its own row actions on\n   * every session row, so this renders nothing unless the archived segment\n   * stands; the host's unarchive button is the entry beside it in the same\n   * seat. Its box is the host's own row-action button (workspace.css).\n   */\n  function DeleteArchivedSession({ sessionId }: { sessionId: string }) {\n    const archived = React.useSyncExternalStore(subscribeView, archivedView)\n    if (!archived) return null\n    const label = copy('archiveDelete')\n    return React.createElement(primitives.Tooltip, {\n      label,\n      side: 'bottom',\n      align: 'end',\n      delayMs: 500,\n      portal: true,\n      children: React.createElement('button', {\n        type: 'button',\n        className: 'dsh-claude-ws-delete',\n        'aria-label': label,\n        title: label,\n        onClick: (event: React.MouseEvent) => {\n          event.stopPropagation()\n          removeArchived(sessionId)\n        },\n      }, React.createElement(primitives.IconTrashOutlineRegular, { size: 14 })),\n    })\n  }\n\n  /** Register the delete action in the host's row-action list, once its declaration is on the ledger. */\n  function registerDeleteAction() {\n    slotsFiber = registerSlotEntries(ctx, [{\n      options: { name: SESSION_ROW_ACTION_SLOT, id: 'claude-style-delete', order: 300 },\n      component: DeleteArchivedSession,\n    }], 'dsh-claude-style: archived delete')\n  }\n\n  /**\n   * The host's view store, once the browser's registration is on the page; the\n   * section keeps its plain label until then, since a segment that cannot drive\n   * the host would lie about the list.\n   */\n  function watch() {\n    if (store !== null) return true\n    const next = hostWorkspaceView(ctx)\n    if (next === null) return false\n    store = next\n    sessions = hostSessions(ctx)\n    reconcile()\n    return true\n  }\n\n  /**\n   * Mark the rows the host mounts as it rebuilds the list, before the frame\n   * paints. The bus holds a large batch back to the task after the paint (D40),\n   * so the rows of a switch would draw the host's 14px/400 title for one frame\n   * where the sidebar's 13px/500 stands; this subscription asks for the paint's\n   * own side of that rule.\n   */\n  function watchAdditions(root: Element) {\n    if (additionsRoot === root) return\n    stopAdditions?.()\n    additionsRoot = root\n    stopAdditions = subscribeMutations(root, { childList: true, subtree: true, beforePaint: true }, records => {\n      for (let r = 0; r < records.length; r++) {\n        const added = records[r].addedNodes\n        for (let n = 0; n < added.length; n++) {\n          const node = added[n]\n          if (node instanceof Element) markPartsWithin(node)\n        }\n      }\n    })\n  }\n\n  function buildControl() {\n    // The shared small segment look (shared/segment-control.css); the feature\n    // class stays for the placement and label crossfade in workspace.css.\n    const group = buildElement('div', `${VIEW_SWITCH_CLASS} dsh-claude-ws-segments`)\n    group.setAttribute('role', 'radiogroup')\n    for (let i = 0; i < SEGMENTS.length; i++) {\n      const item = buildElement('button', 'dsh-claude-ws-segment', '')\n      item.type = 'button'\n      item.setAttribute('role', 'radio')\n      item.setAttribute('data-view', SEGMENTS[i].id)\n      group.appendChild(item)\n    }\n    group.addEventListener('click', event => {\n      const item = closestFrom(event.target, '.dsh-claude-ws-segment')\n      if (item === null) return\n      event.stopPropagation()\n      event.preventDefault()\n      const next = item.getAttribute('data-view')\n      if (next === 'active' || next === 'archived') drive(next)\n    })\n    return group\n  }\n\n  /**\n   * Stand the feature down: the control leaves the page and the section's marks\n   * go with it.\n   *\n   * The host renders the section's heading only while the sidebar is wide\n   * (ui-sidebar's SidebarRoot unmounts it in the rail), while the header and\n   * the list area's own boxes stay mounted: with no heading to lay it over, an\n   * absolutely placed control would paint on the rail's own section buttons.\n   */\n  function dropSection() {\n    segmentPill.release()\n    if (control !== null && control.parentElement !== null) control.parentElement.removeChild(control)\n    control = null\n    labelStamp.release()\n    viewStamp.release()\n    labelWatch?.release()\n    labelWatch = null\n  }\n\n  function sync() {\n    const label = findSection()\n    // No heading to dress: the sidebar is a rail, and the section keeps its\n    // plain look until it is wide again.\n    if (label === null || label.parentElement === null) {\n      dropSection()\n      return\n    }\n    // Until the host's view store is reachable the section keeps its plain label.\n    if (!watch()) {\n      dropSection()\n      return\n    }\n    reconcile()\n    const root = sectionRoot(label)\n    if (root === null) return\n    watchAdditions(root)\n    const header = label.parentElement\n    labelStamp.mark(label)\n    if (control === null || control.parentElement !== header) {\n      if (control !== null && control.parentElement !== null) control.parentElement.removeChild(control)\n      control = buildControl()\n      header.insertBefore(control, header.firstChild)\n    }\n    for (let i = 0; i < control.children.length; i++) {\n      const item = control.children[i]\n      const id = item.getAttribute('data-view')\n      for (let s = 0; s < SEGMENTS.length; s++) {\n        if (SEGMENTS[s].id !== id) continue\n        const text = copy(SEGMENTS[s].key)\n        if (item.textContent !== text) item.textContent = text\n      }\n      const on = id === view\n      if (item.getAttribute('aria-checked') !== (on ? 'true' : 'false')) item.setAttribute('aria-checked', on ? 'true' : 'false')\n    }\n    segmentPill.sync(control)\n    viewStamp.mark(root, view)\n  }\n\n  /**\n   * The pass's read phase: the segment control's own box, taken before this\n   * frame's writes. A pass that builds the control measures it in the write\n   * phase instead (sliding-pill).\n   */\n  function measure() {\n    if (control !== null && control.parentElement !== null) segmentPill.measure(control)\n  }\n\n  registerDeleteAction()\n  ui.workspace = {\n    measure,\n    sync,\n    // The host's row action reads its label from the skin's copy; a locale\n    // change has to reach the entries the host already rendered.\n    onCopyChange() { notifyView() },\n  }\n\n  return () => {\n    disposed = true\n    toast.dispose()\n    if (slotsFiber !== null && typeof slotsFiber.dispose === 'function') slotsFiber.dispose()\n    slotsFiber = null\n    stopAdditions?.()\n    stopAdditions = null\n    additionsRoot = null\n    dropSection()\n    delete ui.workspace\n  }\n}\n"
    },
    {
      "path": "packages/engine/node/http.ts",
      "content": "/**\n * The request handling every private route shares: the fence in front of the\n * user's own data, the method check, the bounded body read and the JSON answer.\n */\nimport type { DshContext, DshRequest, DshResponse } from './dsh'\n\n/**\n * Why a request to a route reading the user's own data must be refused, or\n * undefined when it may proceed.\n *\n * `webServer.register()` hands a plugin route raw requests: the host's own\n * `/api` sits behind a Host/Origin fence and the browser-session cookie, but\n * nothing puts a plugin route there, and these routes read the OS user and the\n * reader's files. So they borrow the host's own check,\n * `connection.requestRejection()` — the fence and authentication `/api`\n * applies. The browser passes it with a same-origin request that carries the\n * session cookie; the desktop shell passes it because it forwards to a loopback\n * Host, drops the page's Origin and attaches the cookie itself. A host without\n * that service cannot authenticate anyone, so the stand-in below serves\n * loopback only: a peer on the loopback interface, a loopback Host (which also\n * defeats DNS rebinding), no cross-site marker, and an Origin, when sent,\n * naming that Host. The peer address is the part of the request the caller\n * cannot write, so it is the one that has to hold.\n *\n * @param ctx - host plugin context.\n * @param req - node request.\n * @returns 401 / 403, or undefined when the request may proceed.\n */\nexport function refusalOf(ctx: DshContext, req: DshRequest) {\n  const connection = ctx.get('connection')\n  if (typeof connection?.requestRejection === 'function') return connection.requestRejection(req)\n  if (!isLoopbackPeer(req.socket.remoteAddress)) return 403\n  const host = req.headers.host\n  if (host !== undefined) {\n    // A Host header that is no host name at all is refused.\n    if (!URL.canParse(`http://${host}`)) return 403\n    const name = new URL(`http://${host}`).hostname\n    if (name !== 'localhost' && name !== '[::1]' && !/^127\\.\\d+\\.\\d+\\.\\d+$/.test(name)) return 403\n  }\n  const site = req.headers['sec-fetch-site']\n  if (site !== undefined && site !== 'same-origin' && site !== 'none') return 403\n  const origin = req.headers.origin\n  if (origin === undefined) return undefined\n  if (!URL.canParse(origin)) return 403\n  return new URL(origin).host === host ? undefined : 403\n}\n\n/**\n * Whether a socket address is this machine: IPv4 `127/8`, IPv6 `::1`, or the\n * IPv4-mapped spelling Node reports for a v4 peer on a dual-stack socket.\n */\nfunction isLoopbackPeer(address: string | undefined) {\n  if (address === undefined) return false\n  const plain = address.startsWith('::ffff:') ? address.slice('::ffff:'.length) : address\n  return plain === '::1' || /^127\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}$/.test(plain)\n}\n\n/** Send one JSON response. */\nexport function sendJson(res: DshResponse, status: number, payload: unknown) {\n  const body = Buffer.from(JSON.stringify(payload))\n  res.writeHead(status, {\n    'content-type': 'application/json; charset=utf-8',\n    'content-length': String(body.byteLength),\n    'cache-control': 'no-store',\n  })\n  res.end(body)\n}\n\n/**\n * Answer 405 for a request whose method the route does not take.\n * @returns whether the request was turned away.\n */\nexport function methodRefused(req: DshRequest, res: DshResponse, methods: string[]) {\n  if (req.method !== undefined && methods.includes(req.method)) return false\n  res.writeHead(405, { allow: methods.join(', ') })\n  res.end()\n  return true\n}\n\n/**\n * The fence every route that reads the user's own data runs first: the\n * host's own check where that service exists, the loopback stand-in\n * otherwise (see refusalOf).\n * @returns whether the request was turned away.\n */\nexport function fenceRefused(ctx: DshContext, req: DshRequest, res: DshResponse) {\n  const refused = refusalOf(ctx, req)\n  if (refused === undefined) return false\n  sendJson(res, refused, { ok: false, error: refused === 401 ? 'unauthorized' : 'forbidden' })\n  return true\n}\n\n/**\n * One bounded request body, or null when it is oversized or unreadable.\n *\n * Over the limit the rest of the body is dropped and the promise answers null:\n * the answer (400 / 413) still has to reach the client, so the socket is not\n * cut here — the caller ends it once the answer has gone out.\n */\nexport function readRequestBody(req: DshRequest, limit: number): Promise<Buffer | null> {\n  return new Promise<Buffer | null>((settle) => {\n    const chunks: Buffer[] = []\n    let size = 0\n    let over = false\n    req.on('data', (chunk: Buffer | string) => {\n      if (over) return\n      size += chunk.length\n      if (size > limit) {\n        over = true\n        settle(null)\n        return\n      }\n      chunks.push(Buffer.from(chunk))\n    })\n    req.on('end', () => { if (!over) settle(Buffer.concat(chunks)) })\n    req.on('error', () => { if (!over) settle(null) })\n  })\n}\n"
    },
    {
      "path": "packages/host/src/index.ts",
      "content": "/**\n * Host half of dsh-claude-style.\n *\n * The skin's effect is browser-only. This half exists for the things a\n * browser-only plugin cannot do:\n *\n *   1. Serve the model copy document. That table is DATA, not code — it ships\n *      beside the bundle as `model-descriptions.json` and the browser half\n *      fetches it at runtime, so the table grows without a rebuild and the\n *      bundle stays free of copy.\n *   2. Serve the bundled code font (and user-supplied text faces) as webfonts.\n *      The skin's code font stack names 'Anthropic Mono Web' first and\n *      'JetBrains Mono' behind it, and a face renders only when its family\n *      resolves — most systems have never installed either. The JetBrains\n *      files ship in this package (SIL OFL), so the fonts route hands them to\n *      the browser half's @font-face and the code face works with zero system\n *      installs. The Anthropic Sans/Serif/Mono faces are NOT in the npm\n *      package (they remain Anthropic's property), but a user who drops them\n *      into `$DSH_HOME/dsh-claude-style/fonts/` gets the same zero-install\n *      treatment; a missing file simply 404s and the stack falls back to a\n *      system-installed copy, then to the look-alike faces this package does\n *      ship (Inter, Noto Serif, JetBrains Mono — SIL OFL).\n *   3. Resolve the OS user once for the browser half. The username route answers\n *      a single GET and the browser caches it; it runs the host's own request\n *      fence first — see refusalOf() in routes.ts.\n *   4. Serve Deepy's animation sheets. The DeepSeek brand's pixel whale plays\n *      more sprite sheets than are worth inlining into the bundle, so they ship\n *      as files beside it and the browser fetches each one the first time its\n *      animation plays.\n *\n * The registrations are defensive. A host without a web server, or with the\n * route prefix already taken, or with the settings service absent, must still\n * activate the plugin: a failed host fiber also drops the client bundle from\n * the module graph and the whole skin with it. The browser half falls back to\n * its defaults when either surface is missing.\n *\n * The routes live in routes.ts, the HDSL account contract in hdsl.ts, and the\n * settings surface in settings.ts; this file only mounts them.\n */\nimport { PACKAGE_NAME } from '@dsh-claude-style/contracts/package'\nimport { registerRoutes } from './routes.js'\nimport type { DshContext, DshScope } from '@dsh-claude-style/engine/node/dsh'\nimport { registerSettings } from './settings.js'\nimport { registerWidgetUsage } from './widget-usage.js'\n\nexport const name = PACKAGE_NAME\nexport { Config } from './settings.js'\n\n/**\n * Register the plugin's host surfaces.\n * @param ctx - host plugin context.\n */\nexport function apply(ctx: DshContext) {\n  // Always register through inject, never on the bare ctx. `ctx.get()` reads a\n  // service leniently (no inject declaration needed), but the PROPERTY access\n  // inside registerRoutes (`scope.webServer`) is gated by the fiber's inject\n  // declaration, and a host half re-applies while the web server is already\n  // running (a generation relink after a client-bundle rebuild). inject()\n  // waits for the service and hands registerRoutes a scope that HAS the\n  // declaration, so both a boot-time apply and a hot relink register. A host\n  // without a web server simply waits here, and the skin still activates.\n  if (typeof ctx.inject === 'function') ctx.inject(['webServer'], (scope: DshScope) => { registerRoutes(ctx, scope) })\n  else registerRoutes(ctx, ctx as DshScope)\n\n  registerSettings(ctx)\n  registerWidgetUsage(ctx)\n}\n"
    },
    {
      "path": "packages/host/src/routes.ts",
      "content": "/**\n * The plugin's host routes: everything the browser half cannot reach itself.\n *\n * These are the surfaces D75 describes — the model copy document, the webfonts,\n * the OS user, the HDSL account, the routed assets, session deletion, the\n * usage and search roll-ups, the peak rate catalog and the reader's brand\n * images (packages/host/src/brand.ts) — each registered on the\n * host's web server under this plugin's route prefix. Every route is\n * registered on its own: one path the web server refuses is reported, and the\n * other routes still register.\n *\n * The paths are the shared contract (`@dsh-claude-style/contracts/routes`, * D73): the browser half addresses the same names.\n */\nimport { PACKAGE_NAME } from '@dsh-claude-style/contracts/package'\nimport { HDSL_PATH, HDSL_SKIN_PATH, PEAKRATE_PATH, PRICES_PATH, ROUTE_PREFIX, SESSION_COST_PATH, SESSION_DELETE_PATH, SESSION_SEARCH_PATH, USAGE_PATH, USERNAME_PATH } from '@dsh-claude-style/contracts/routes'\nimport { existsSync, readFileSync, readdirSync, realpathSync, rmSync, statSync } from 'node:fs'\nimport { userInfo } from 'node:os'\nimport { dirname, join, resolve, sep } from 'node:path'\nimport { brandRoutes } from './brand.js'\nimport type { DshContext, DshRequest, DshResponse, DshRoute, DshScope } from '@dsh-claude-style/engine/node/dsh'\nimport { harnessPath } from '@dsh-claude-style/engine/node/harness-home'\nimport { pluginPath } from './harness-home.js'\nimport { fenceRefused, methodRefused, readRequestBody, refusalOf, sendJson } from '@dsh-claude-style/engine/node/http'\nimport { createStaticFiles } from '@dsh-claude-style/engine/node/static-files'\nimport { createHdslAccount } from './hdsl.js'\nimport type { HdslReading } from './hdsl.js'\nimport { packageRoot } from './package-root.js'\nimport { createPeakRate } from './peakrate.js'\nimport { createPrices } from './prices.js'\nimport { QUERY_MAX, createSessionSearch } from './search.js'\nimport { billingRowsOf, createSessionCost } from './session-cost.js'\nimport { sessionDirectoryName } from './session-name.js'\nimport { createUsage } from './usage.js'\n\n/** The copy document, built from `packages/client/data/model-descriptions.json` by scripts/build.mjs. */\nconst COPY_FILE = 'model-descriptions.json'\n\n/** The custom price rows one ask carries: one `b` query parameter per row, plus the currency they are written in. */\nconst BILLING_ROWS_MAX = 32\nconst BILLING_ROW_MAX = 256\n\nfunction readBillingRows(query: URLSearchParams) {\n  const currency = query.get('cur')\n  const rows = query.getAll('b').slice(0, BILLING_ROWS_MAX).filter(row => row.length <= BILLING_ROW_MAX)\n  return billingRowsOf(rows, currency === 'CNY' || currency === 'USD' ? currency : null)\n}\n/**\n * Webfonts this plugin serves under `${ROUTE_PREFIX}/fonts/`, mapped to their\n * content type. The table is a whitelist: the filename is the whole request\n * contract, so no path outside the two directories below is reachable and no\n * path traversal is possible.\n *\n * A name is looked up in the user's own drop point first — the harness home's\n * `dsh-claude-style/fonts/` — and then in the package's `lib/fonts/` (D75). The\n * JetBrains Mono files and the two look-alike faces behind the Anthropic ones\n * (Inter, Noto Serif) ship in the npm package; the Anthropic faces do not\n * (copyright), so only a copy the user dropped in answers them. A name neither\n * directory holds is absent: sendFile's ENOENT becomes a 404, which the browser\n * half's font stacks fall back from.\n */\nconst FONT_FILES = {\n  'JetBrainsMonoVariable.ttf': 'font/ttf',\n  'JetBrainsMonoItalicVariable.ttf': 'font/ttf',\n  'AnthropicSansWebText.ttf': 'font/ttf',\n  'AnthropicSerifWebText.ttf': 'font/ttf',\n  'AnthropicMonoWeb.ttf': 'font/ttf',\n  'InterVariable.woff2': 'font/woff2',\n  'NotoSerifVariable.woff2': 'font/woff2',\n}\n/**\n * The assets the build routed rather than inlined, served under\n * `${ROUTE_PREFIX}/assets/` from the build output in `lib/assets/`\n *\n * The request name is the whole contract: it must be a key of the build's\n * manifest, which is `<content hash>.<ext>` — no separator, no dot segment —\n * so nothing outside that directory is reachable and a name the build did not\n * produce is a 404. The name carries the content hash, so the answer may be\n * cached for good. A text asset is stored brotli-compressed beside its name:\n * a client that takes brotli receives it as it lies, and one that does not\n * gets it decompressed, so the package carries the sheets once, small.\n */\nconst ASSETS_PATH = `${ROUTE_PREFIX}/assets/`\n/** Largest deletion request body read; a real one carries one id. */\nconst DELETE_BODY_MAX = 4096\n\n/**\n * An id the deletion route takes: the characters a plugin-generated id carries\n * (`:`, `@`), and none that could name a place of its own.\n *\n * The stored name below escapes `/`, `\\` and `~` as well, so an id carrying one\n * is refused here rather than silently resolved through the escape: a client\n * naming a path segment is not naming a session.\n */\nconst SESSION_ID_RE = /^[A-Za-z0-9._\\-:@]{1,200}$/\n\n/**\n * Whether the host holds this session open right now.\n *\n * A live session's log is open and being appended to, so its directory must not\n * be removed under the writer. A sessions service that offers no way to read\n * its live set answers \"live\": an unreadable set cannot authorize the\n * deletion. A read that throws fails the request (500), which refuses the\n * deletion as well.\n */\nfunction sessionIsLive(ctx: DshContext, sessionId: string): boolean {\n  const sessions = ctx.get('sessions')\n  // A host with no sessions service holds nothing open.\n  if (sessions === null || sessions === undefined) return false\n  if (typeof sessions.get === 'function') {\n    const found = sessions.get(sessionId)\n    return found !== undefined && found !== null\n  }\n  if (typeof sessions.list === 'function') {\n    const listed = sessions.list()\n    if (Array.isArray(listed)) {\n      return listed.some((item) => (typeof item === 'string' ? item : item?.id ?? item?.sessionId) === sessionId)\n    }\n  }\n  return true\n}\n\n/**\n * Drop one id from the workspace registry's archive set, durably.\n *\n * The registry is read at request time: it mounts with the workspace domain and\n * can complete after this plugin. A host without one has no archive set to\n * update — and no archived list to delete from — while a failing unarchive\n * propagates: the route answers 500, the row stays, and the next delete\n * retries through the miss branch.\n */\nasync function unarchiveSession(ctx: DshContext, sessionId: string) {\n  const registry = ctx.get('workspaceRegistry')\n  if (typeof registry?.unarchiveSession !== 'function') return\n  await registry.unarchiveSession(sessionId)\n}\n\n/**\n * Delete one stored session: the directory named by the id under one of the\n * sessions root's working-directory directories, and the id's entry in the\n * workspace registry's archive set.\n *\n * The id reaches the filesystem as the name the harness stores it under, never\n * as its own spelling, and only after the id check: the lookup is by exact name\n * and the resolved directory must stay inside the sessions root.\n *\n * The archive set can name a session whose stored directory is already gone —\n * an earlier removal took the directory while the registry entry stayed, and\n * the stale session summary keeps its row on the archived list. The miss\n * answers success too: the registry's unarchive runs no existence check and\n * resolves without writing for an id that is not archived, so the entry leaves\n * the set either way and the row is gone for good instead of coming back on\n * the next reload.\n */\nasync function deleteSession(ctx: DshContext, req: DshRequest, res: DshResponse) {\n  const refused = refusalOf(ctx, req)\n  if (refused !== undefined) {\n    sendJson(res, refused, { ok: false, error: refused === 401 ? 'unauthorized' : 'forbidden' })\n    return\n  }\n  const raw = await readRequestBody(req, DELETE_BODY_MAX)\n  if (raw === null) {\n    // An oversized body leaves its remainder unread: the socket is ended once\n    // this request's answer is out, never before it.\n    res.once('finish', () => req.destroy())\n  }\n  let request = null\n  try {\n    request = raw === null ? null : JSON.parse(raw.toString('utf8'))\n  } catch {\n    // A body that is not JSON is the client's error: the id check below answers 400.\n    request = null\n  }\n  const sessionId = request !== null && typeof request.sessionId === 'string' ? request.sessionId : ''\n  if (!SESSION_ID_RE.test(sessionId)) {\n    sendJson(res, 400, { ok: false, error: 'invalid session id' })\n    return\n  }\n  // The id is looked up under the name the storage holds it under, never under\n  // its own spelling: `:` and `@` in a plugin-generated id are escaped there.\n  const storedName = sessionDirectoryName(sessionId)\n  if (sessionIsLive(ctx, sessionId)) {\n    sendJson(res, 409, { ok: false, error: 'session is open' })\n    return\n  }\n  const root = resolve(harnessPath(ctx, 'sessions'))\n  let dir = null\n  // The root listing is the storage's own answer, so a failure there is a\n  // fault and propagates to the route's 500 answer; a candidate that does not\n  // exist is \"not under this entry\", and the scan moves past it.\n  for (const entry of readdirSync(root)) {\n    const candidate = join(root, entry, storedName)\n    if (statSync(candidate, { throwIfNoEntry: false })?.isDirectory() === true) {\n      dir = candidate\n      break\n    }\n  }\n  if (dir === null) {\n    await unarchiveSession(ctx, sessionId)\n    sendJson(res, 200, { ok: true, ghost: true })\n    return\n  }\n  // The comparison has to be between resolved paths: an entry inside the root\n  // that is itself a symlink carries a recursive removal out of it, and\n  // `resolve` only normalizes the spelling (D75).\n  cons